"""Seating charts laid out in rows."""

from typing import List
from rosterkit.models import Student

def _name_key(pupil: Student) -> tuple:
    return (
        pupil.last_name.casefold(),
        pupil.first_name.casefold()
    )

def _sorted_students(
    students: List[Student]
) -> List[Student]:
    if not students:
        raise ValueError("no students to seat")
    return sorted(students, key=_name_key)

def _row_line(number: int, group: List[Student]) -> str:
    names = " | ".join(peer.display_name for peer in group)
    return f"Row {number}: {names}"

def _make_rows(
    ordered: List[Student], seats: int
) -> List[str]:
    rows = []
    for start in range(0, len(ordered), seats):
        group = ordered[start:start + seats]
        rows.append(_row_line(start // seats + 1, group))
    return rows

# ---
def seating_rows(
    students: List[Student], seats: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    if seats <= 0:
        raise ValueError(f"bad seat count: {seats}")
    ordered = _sorted_students(students)
    return _make_rows(ordered, seats)

