import unittest

from tests.support import data_file
from rosterkit.seating import seating_rows
from rosterkit.reader import read_roster
from rosterkit.models import Student

def _pupil(family: str, given: str) -> Student:
    return Student("id" + family, family, given, "A")

def _trio() -> list:
    return [
        _pupil("Halloway", "Juno"),
        _pupil("Dunmere", "Piet"),
        _pupil("Abbot", "Cass")
    ]

class SeatingTests(unittest.TestCase):
    # ---
    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seating_rows(_trio(), 2),
            [
                "Row 1: Abbot, Cass | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    # ---
    def test_first_name_breaks_ties(self):
        pupils = [
            _pupil("Lane", "Zed"),
            _pupil("Lane", "Amy")
        ]
        self.assertEqual(
            seating_rows(pupils, 5),
            ["Row 1: Lane, Amy | Lane, Zed"]
        )

    # ---
    def test_roster_file(self):
        pupils = read_roster(data_file("roster.csv"))
        rows = seating_rows(pupils, 2)
        self.assertEqual(len(rows), (len(pupils) + 1) // 2)

    # ---
    def test_bad_seat_counts(self):
        pupils = [_pupil("Lane", "Amy")]
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(pupils, seats)

    # ---
    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
